﻿import { BaseComponent } from "@/baseComponent";
import { getComponentById } from "@/componentStore";
export class WaterMark extends BaseComponent {
    wrapper: HTMLElement
    options?: any
    ob: MutationObserver
    mask?: HTMLElement
    originalDisplay: string = ''

    constructor(wrapper: HTMLElement) {
        super()
        this.wrapper = wrapper || window.document.body

        window.addEventListener('beforeprint', this.handleBeforePrint.bind(this))
        window.addEventListener('afterprint', this.handleAfterPrint.bind(this))

        this.ob = new MutationObserver((entries) => {
            for (const entry of entries) {
                if (entry.type === 'childList' || entry.type === "attributes") {
                    const removeNodes = entry.removedNodes;
                    removeNodes.forEach((node) => {
                        if (node === this.mask) {
                            this.setWatermark(this.options);
                        }

                        if (entry.target === this.mask) {
                            this.setWatermark(this.options);
                        }
                    });
                }
            }
        });

        this.ob.observe(this.wrapper, {
            attributes: true,
            childList: true,
            characterData: true,
            subtree: true,
        });
    }

    setWatermark(options: any | undefined) {
        if (this.mask) {
            this.mask.remove();
        }
        this.options = options;
        this.mask = createDiv();
        let url = drawMask(options)
        this.mask.style.backgroundSize = `${options.gapX + options.width}px`;
        this.mask.style.backgroundImage = `url(${url})`;
        //this.mask.src = url!
        this.wrapper.appendChild(this.mask);
    }

    // 打印前隐藏水印
    handleBeforePrint() {
        if (this.mask) {
            // 暂时断开观察器，避免打印时触发
            this.ob.disconnect();
            this.originalDisplay = this.mask.style.display;
            this.mask.style.display = 'none';

        }
    }

    // 打印后恢复水印
    handleAfterPrint() {
        if (this.mask) {
            this.mask.style.display = this.originalDisplay || '';

            // 重新连接观察器
            this.ob.observe(this.wrapper, {
                attributes: true,
                childList: true,
                characterData: true,
                subtree: true,
            });
        }
    }

    dispose() {
        this.ob.disconnect();
    }

    static setWatermark(id: string, wrapper: HTMLElement, options: any) {
        let com = getComponentById(id, () => {
            return new WaterMark(wrapper)
        })
        com.setWatermark(options);
    }

    static refreshWatermark(id: string) {
        const com = getComponentById(id)
        if (com) {
            // 下一帧再重新绘制
            window.requestAnimationFrame(() => {
                com.setWatermark(com.options);
            })
        }
    }
}

function createDiv(): HTMLElement {
    var d = document.createElement("div");
    d.style.position = "fixed";
    d.style.left = '0';
    d.style.top = '0';
    d.style.width = "100%";
    d.style.height = "100%";
    d.style.pointerEvents = "none";
    d.style.backgroundRepeat = "repeat";
    d.style.zIndex = Number.MAX_SAFE_INTEGER.toString();
    return d;
}

function getFontColor(color: string) {
    if (color) return color;
    const cssParameters = getComputedStyle(document.documentElement)
    const value = cssParameters.getPropertyValue('--watermark-color')
    return value
}

function drawMask({
    top,
    width,
    height,
    gapX,
    gapY,
    rotate,
    alpha,
    lineSpace,
    fontSize,
    fontColor,
    contents
}) {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) {
        console.warn('Current environment does not support Canvas, cannot draw watermarks.');
        return;
    }
    const ratio = window.devicePixelRatio || 1;
    const canvasWidth = (gapX + width) * ratio;
    const canvasHeight = (gapY + height) * ratio;
    canvas.width = canvasWidth;
    canvas.height = canvasHeight;
    canvas.style.width = `${gapX + width}px`;
    canvas.style.height = `${gapY + height}px`;

    ctx.rotate((Math.PI / 180) * Number(rotate));
    ctx.globalAlpha = alpha;

    const markWidth = width * ratio;
    const markHeight = height * ratio;

    ctx.fillStyle = 'transparent';
    ctx.fillRect(0, 0, markWidth, markHeight);

    let fontFamily = 'sans-serif';
    let fontWeight = 'normal';
    let textAlign: CanvasTextAlign = 'start';
    let fontStyle = 'normal';
    const color = getFontColor(fontColor)
    const markSize = Number(fontSize) * ratio;
    for (var i = 0; i < contents.length; i++) {
        let text = contents[i];
        top += lineSpace;
        ctx.font = `${fontStyle} normal ${fontWeight} ${markSize}px/${markHeight}px ${fontFamily}`;
        ctx.textAlign = textAlign;
        ctx.textBaseline = 'top';
        ctx.fillStyle = color;
        ctx.fillText(text, 0, top * ratio);
    }
    return canvas.toDataURL("image/png");
}
